'use client';

import { Edit3, Eye, MoreHorizontal, Plus, UserRound, Users } from 'lucide-react';
import Link from 'next/link';
import { useState } from 'react';
import { toast } from 'sonner';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { useDepartments, useEmployees } from '@/lib/queries';
import { Avatar, Button, Card, DataTableShell, EmptyState, ErrorState, Input, PageHeader, Select, Spinner, StatusBadge, TableCell, TableHeader } from '@/components/ui';
import { ConfirmDialog } from '@/components/confirm-dialog';

export default function AdminEmployeesPage() { const [search, setSearch] = useState(''); const [department, setDepartment] = useState(''); const [status, setStatus] = useState(''); const [page, setPage] = useState(1); const params = new URLSearchParams({ page: String(page), limit: '8' }); if (search) params.set('search', search); if (department) params.set('department', department); if (status) params.set('status', status); const employees = useEmployees(params); const departments = useDepartments(); const client = useQueryClient(); const [deleting, setDeleting] = useState<string | null>(null); const deactivate = useMutation({ mutationFn: api.deactivateEmployee, onSuccess: () => { toast.success('Employee deactivated'); client.invalidateQueries({ queryKey: ['employees'] }); setDeleting(null); }, onError: (error) => toast.error(error.message) }); return <div><PageHeader eyebrow="People directory" title="Employees" description="Keep every person, team, and reporting line in one calm place." action={<Link href="/admin/employees/new"><Button><Plus className="h-4 w-4" />Add employee</Button></Link>} /><Card className="overflow-hidden"><div className="flex flex-col gap-3 border-b border-[#e8e4dc] p-4 sm:flex-row sm:items-center"><Input aria-label="Search employees" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Search by name, email, or ID" className="sm:max-w-xs" /><Select aria-label="Filter by department" value={department} onChange={(event) => { setDepartment(event.target.value); setPage(1); }} className="sm:w-48"><option value="">All departments</option>{(departments.data ?? []).map((item) => <option key={item}>{item}</option>)}</Select><Select aria-label="Filter by status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }} className="sm:w-40"><option value="">All statuses</option><option value="ACTIVE">Active</option><option value="ON_LEAVE">On leave</option><option value="INACTIVE">Inactive</option></Select><span className="ml-auto text-xs font-semibold text-[#92939a]">{employees.data?.total ?? 0} people</span></div>{employees.isLoading ? <div className="p-6"><Spinner /></div> : employees.isError ? <div className="p-5"><ErrorState message={employees.error.message} retry={() => employees.refetch()} /></div> : employees.data?.items.length ? <DataTableShell><TableHeader><th className="px-5 py-3">Person</th><th className="px-5 py-3">Department</th><th className="px-5 py-3">Role</th><th className="px-5 py-3">Location</th><th className="px-5 py-3">Status</th><th className="px-5 py-3 text-right">Actions</th></TableHeader><tbody className="divide-y divide-[#f0ede8]">{employees.data.items.map((person) => <tr key={person.id} className="transition hover:bg-[#fffdf9]"><TableCell><div className="flex items-center gap-3"><Avatar name={`${person.firstName} ${person.lastName}`} src={person.avatarUrl} size="sm" /><div><p className="text-sm font-bold">{person.firstName} {person.lastName}</p><p className="text-xs text-[#8a8b91]">{person.employeeCode} · {person.email}</p></div></div></TableCell><TableCell><span className="text-sm font-semibold">{person.department}</span></TableCell><TableCell><span className="text-sm text-[#777982]">{person.designation}</span></TableCell><TableCell><span className="text-sm text-[#777982]">{person.location ?? '—'}</span></TableCell><TableCell><StatusBadge status={person.employmentStatus} /></TableCell><TableCell><div className="flex justify-end gap-1"><Link href={`/employees/${person.id}`} aria-label={`View ${person.firstName}`} className="flex h-9 w-9 items-center justify-center rounded-lg text-[#777982] hover:bg-[#f3f1ec]"><Eye className="h-4 w-4" /></Link><Link href={`/admin/employees/${person.id}`} aria-label={`Edit ${person.firstName}`} className="flex h-9 w-9 items-center justify-center rounded-lg text-[#777982] hover:bg-[#f3f1ec]"><Edit3 className="h-4 w-4" /></Link><button aria-label={`Deactivate ${person.firstName}`} className="flex h-9 w-9 items-center justify-center rounded-lg text-[#777982] hover:bg-[#fff0ed] hover:text-[#c24b3d]" onClick={() => setDeleting(person.id)}><MoreHorizontal className="h-4 w-4" /></button></div></TableCell></tr>)}</tbody></DataTableShell> : <div className="p-5"><EmptyState title="No employees found" description="Try changing the search or filters." action={<Link href="/admin/employees/new"><Button size="sm">Add first employee</Button></Link>} /></div>}<div className="flex items-center justify-between border-t border-[#e8e4dc] p-4"><p className="text-xs text-[#85878d]">Page {employees.data?.page ?? page} of {employees.data?.totalPages ?? 1}</p><div className="flex gap-2"><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={!employees.data || page >= employees.data.totalPages} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div></Card><ConfirmDialog open={Boolean(deleting)} title="Deactivate employee?" description="They will remain in your records but no longer appear as an active team member." onCancel={() => setDeleting(null)} onConfirm={() => deleting && deactivate.mutate(deleting)} loading={deactivate.isPending} /></div>; }
