'use client';
import { AlertTriangle, X } from 'lucide-react';
import { Button, IconButton } from './ui';
export function ConfirmDialog({ open, title, description, onConfirm, onCancel, loading }: { open: boolean; title: string; description: string; onConfirm: () => void; onCancel: () => void; loading?: boolean }) { if (!open) return null; return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#1f2229]/30 p-4 backdrop-blur-sm" role="dialog" aria-modal="true"><div className="w-full max-w-sm rounded-2xl border border-[#e8e4dc] bg-white p-5 shadow-2xl"><div className="flex items-start justify-between"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#fff0ed] text-[#d95342]"><AlertTriangle className="h-5 w-5" /></span><IconButton label="Close dialog" onClick={onCancel}><X className="h-4 w-4" /></IconButton></div><h2 className="mt-4 font-display text-2xl">{title}</h2><p className="mt-2 text-sm leading-6 text-[#777982]">{description}</p><div className="mt-6 flex justify-end gap-2"><Button variant="outline" onClick={onCancel}>Cancel</Button><Button variant="danger" onClick={onConfirm} disabled={loading}>{loading ? 'Working…' : 'Confirm'}</Button></div></div></div>; }
